inputParameters.expression:
(function () {
  function asArray(value) {
    if (value == null) return [];
    if (Array.isArray(value)) return value;
    if (typeof value.size === 'function' && typeof value.get === 'function') {
      var list = [];
      for (var i = 0; i < value.size(); i++) list.push(value.get(i));
      return list;
    }
    return [value];
  }
  function pick(obj, key) {
    if (obj == null) return null;
    if (typeof obj.get === 'function') {
      var gv = obj.get(key);
      if (gv != null) return gv;
    }
    return obj[key];
  }

  function extractList(body) {
    if (!body) return [];
    if (typeof body === 'string') {
      try {
        body = JSON.parse(body);
      } catch (e) {
        return [];
      }
    }
    var data = pick(body, 'data');
    if (data == null) data = pick(body, 'result');
    if (Array.isArray(data) || (data != null && typeof data.size === 'function')) return asArray(data);
    return data ? [data] : [];
  }

  function appendUnique(target, items) {
    asArray(items).forEach(function (item) {
      if (!item) return;
      var exists = target.some(function (existing) {
        return pick(existing, 'medTechRequestId') === pick(item, 'medTechRequestId')
          && pick(existing, 'sourceId') === pick(item, 'sourceId');
      });
      if (!exists) target.push(item);
    });
  }

  var merged = [];
  var failures = [];
  var splitSummary = $.splitSummary || {};

  var lisStatus = Number($.lisStatusCode);
  if (lisStatus >= 200 && lisStatus < 300) {
    appendUnique(merged, extractList($.lisBody));
  } else if ($.lisBody != null || $.lisStatusCode != null) {
    failures.push({ branch: 'LIS', statusCode: $.lisStatusCode, body: $.lisBody });
  }

  var pacsStatus = Number($.pacsStatusCode);
  if (pacsStatus >= 200 && pacsStatus < 300) {
    appendUnique(merged, extractList($.pacsBody));
  } else if ($.pacsBody != null || $.pacsStatusCode != null) {
    failures.push({ branch: 'PACS', statusCode: $.pacsStatusCode, body: $.pacsBody });
  }

  return {
    returnCode: failures.length === 0 ? '200' : '500',
    errorMessage: failures.length === 0 ? '成功' : ('部分调用失败: ' + failures.length),
    data: merged,
    BusinessMethod: pick(splitSummary, 'BusinessMethod'),
    BusinessCode: pick(splitSummary, 'BusinessCode'),
    lisItemCount: asArray(pick(splitSummary, 'lisItems')).length,
    pacsItemCount: asArray(pick(splitSummary, 'pacsItems')).length,
    skippedItemCount: pick(splitSummary, 'skippedItemCount') || 0,
    failures: failures
  };
})()
